using System;using System.Collections.Generic;using System.IO;using System.Linq;using System.Text;using System.Threading.Tasks;namespace Mapping{    /// <summary>    ///  È«¿þÀÌ Mapping    /// </summary>    public class HWConverter : MapConverterSkeleton    {        static HWConverter()        {            MapConverterMap.LookupWithDefault("HW", new HWConverter());        }        private BinCode[,,,] OriginalBinCodes { get; set; }        public HWConverter()        {        }        public override MapData Read(string mapFile, bool isOriginalMap = false)        {            if (string.IsNullOrWhiteSpace(mapFile))            {                throw new ArgumentNullException(nameof(mapFile));            }            var fileType = Path.GetExtension(mapFile);            using (FileStream fs = new FileStream(mapFile, FileMode.Open, FileAccess.Read))            {                using (StreamReader sr = new StreamReader(fs, Encoding.Default))                {                    if (fileType.Contains("KA"))                    {                        var md = this.ReadKA(sr, isOriginalMap);                        md.SubstrateID = Path.GetFileNameWithoutExtension(mapFile);                        return md;                    }                    else                    {                        var md = this.ReadZW(sr, isOriginalMap);                        md.SubstrateID = Path.GetFileNameWithoutExtension(mapFile);                        return md;                    }                }            }        }        private MapData ReadKA(StreamReader sr, bool isOriginalMap = false)        {            var mapData = new MapData();            //ROUTST            sr.ReadLine();            //VERSID            sr.ReadLine();            //TIMEST            sr.ReadLine();            //MAPTYP            sr.ReadLine();            //DESIGN            sr.ReadLine();            //LOTMEA            sr.ReadLine();            //REFCNT            sr.ReadLine();            //REFBIN            sr.ReadLine();            //REFTP1            sr.ReadLine();            //REFPX1            sr.ReadLine();            //REFPY1            sr.ReadLine();            //REFTP2            sr.ReadLine();            //REFPX2            sr.ReadLine();            //REFPY2            sr.ReadLine();            //REFTP3            sr.ReadLine();            //REFPX3            sr.ReadLine();            //REFPY3            sr.ReadLine();            //FFROT1            sr.ReadLine();            //FNLOC1            sr.ReadLine();            //ORLOC1            sr.ReadLine();            //ROWCNT            var line = sr.ReadLine();            mapData.Rows = Convert.ToInt32(line.Remove(0, 7));            //COLCNT            line = sr.ReadLine();            mapData.Columns = Convert.ToInt32(line.Remove(0, 7));            //WAFDIA            sr.ReadLine();            //XDIES1            sr.ReadLine();            //YDIES1            sr.ReadLine();            // Null Bin            //mapData.NullBin = Bin.CreateNullBin(BinFormatType.HexaDecimal,"00");            mapData.Bins = new BinCollection();            //PASBIN            line = sr.ReadLine();            var str = line.Remove(0, 7);            var binCodes = str.Split(',');            foreach (var code in binCodes)            {                var binCode = new BinCode(BinFormatType.HexaDecimal, str);                var bin = new Bin(binCode, true);                mapData.Bins.Add(bin);            }            //SUMPAS            sr.ReadLine();            //COMPRE            sr.ReadLine();            //SKIPDI            sr.ReadLine();            //REMARK            sr.ReadLine();            //MAPID1            sr.ReadLine();            // BinCode            mapData.BinCodes = new BinCode[1, 1, mapData.Rows, mapData.Columns];            int r = 0;            do            {                line = sr.ReadLine();                if (line == "[WorkingMap]" && !isOriginalMap)                {                    r = 0;                    mapData.BinCodes= new BinCode[1, 1, mapData.Rows, mapData.Columns];                    continue;                }                if (line is null|| (line == "[WorkingMap]" && isOriginalMap))                {                    break;                }                if (string.IsNullOrWhiteSpace(line))                {                    continue;                }                var blank = line.Remove(0, 7);                if (string.IsNullOrWhiteSpace(blank))                {                    continue;                }                var codes = new List<string>();                for (int i = 0; i < (mapData.Columns) * 2; i = i + 2)                {                    var str1 = blank.Substring(i, 2);                    codes.Add(str1);                }                int c = 0;                foreach (var code in codes)                {                    string newCode;                    if (code.Equals("XX"))                    {                        newCode = "FF";                    }                    else                    {                        newCode = code;                    }                    mapData.BinCodes[0, 0, r, c] = new BinCode(BinFormatType.HexaDecimal, newCode);                    c++;                    var binCode = new BinCode(BinFormatType.HexaDecimal, newCode);                    var bin = new Bin(binCode, false);                    var foundBin = mapData.Bins.Find(x => x.Code == binCode);                    //if ((foundBin is null) && binCode != mapData.NullBin.Code)                    if ((foundBin is null))                    {                        mapData.Bins.Add(bin);                    }                }                r++;            } while (true);            if (isOriginalMap)                OriginalBinCodes = mapData.BinCodes;            return mapData;        }        private MapData ReadZW(StreamReader sr, bool isOriginalMap = false)        {            var mapData = new MapData();            //VERSID            sr.ReadLine();            //WAFDIA            sr.ReadLine();            //COLCNT            var line = sr.ReadLine();            mapData.Columns = Convert.ToInt32(line.Remove(0, 7));            //ROWCNT            line = sr.ReadLine();            mapData.Rows = Convert.ToInt32(line.Remove(0, 7));            //COMPRE            sr.ReadLine();            //DESIGN            sr.ReadLine();            //FNLOC1            sr.ReadLine();            //LOTMEA            sr.ReadLine();            //MAPTYP            sr.ReadLine();            //ORLOC1            sr.ReadLine();            //PPFLAG            sr.ReadLine();            //REFBIN            sr.ReadLine();            //REFCNT            sr.ReadLine();            //REFPX1            sr.ReadLine();            //REFPY1            sr.ReadLine();            //REFTP1            sr.ReadLine();            //REFPX2            sr.ReadLine();            //REFPY2            sr.ReadLine();            //REFTP2            sr.ReadLine();            line = sr.ReadLine();            if (!line.Contains("REFPX3"))                goto _SUMPAS;            //REFPY3            sr.ReadLine();            //REFTP3            sr.ReadLine();            //REFPX4            sr.ReadLine();            //REFPY4            sr.ReadLine();            //REFTP4            sr.ReadLine();            //SKIPDI            sr.ReadLine();        _SUMPAS:            //SUMPAS            sr.ReadLine();            //PICKCT            sr.ReadLine();            //PASB01            sr.ReadLine();            // Null Bin            //mapData.NullBin = Bin.CreateNullBin(BinFormatType.HexaDecimal, "00");            mapData.Bins = new BinCollection();            //PASBIN            line = sr.ReadLine();            var str = line.Remove(0, 7);            var binCodes = str.Split(',');            foreach (var code in binCodes)            {                var binCode = new BinCode(BinFormatType.HexaDecimal, code);                var bin = new Bin(binCode, true);                mapData.Bins.Add(bin);            }            //PICK01            sr.ReadLine();            //SUMP01            sr.ReadLine();            //TOMEST            sr.ReadLine();            //MAPID1            sr.ReadLine();            // BinCode            mapData.BinCodes = new BinCode[1, 1, mapData.Rows, mapData.Columns];            int r = 0;            do            {                line = sr.ReadLine();                if (line == "[WorkingMap]" && !isOriginalMap)                {                    r = 0;                    mapData.BinCodes = new BinCode[1, 1, mapData.Rows, mapData.Columns];                    continue;                }                if (line is null || (line == "[WorkingMap]" && isOriginalMap))                {                    break;                }                if (string.IsNullOrWhiteSpace(line))                {                    continue;                }                var blank = line.Remove(0, 7);                if (string.IsNullOrWhiteSpace(blank))                {                    continue;                }                var codes = new List<string>();                for (int i = 0; i < (mapData.Columns) * 2; i = i + 2)                {                    var str1 = blank.Substring(i, 2);                    codes.Add(str1);                }                int c = 0;                foreach (var code in codes)                {                    string newCode;                    if (code.Equals("XX"))                    {                        newCode = "FF";                    }                    else                    {                        newCode = code;                    }                    mapData.BinCodes[0, 0, r, c] = new BinCode(BinFormatType.HexaDecimal, newCode);                    c++;                    var binCode = new BinCode(BinFormatType.HexaDecimal, newCode);                    var bin = new Bin(binCode, false);                    var foundBin = mapData.Bins.Find(x => x.Code == binCode);                    if ((foundBin is null))                    {                        mapData.Bins.Add(bin);                    }                }                r++;            } while (true);            if (isOriginalMap)                OriginalBinCodes = mapData.BinCodes;            return mapData;        }        public override void Save(Map map, string fileName)        {            if (string.IsNullOrWhiteSpace(fileName))            {                throw new ArgumentNullException(nameof(fileName));            }            var index = fileName.LastIndexOf('.') + 1;            var fileType = fileName.Substring(index);            using (FileStream fs = new FileStream(Path.GetFullPath(fileName), FileMode.OpenOrCreate, FileAccess.ReadWrite))            {                using (StreamWriter sw = new StreamWriter(fs, Encoding.Default))                {                    if (fileType.Contains("ZW"))                    {                        SaveZW(map, sw);                    }                    else                    {                        SaveKA(map, sw);                    }                }            }        }        private void SaveKA(Map map, StreamWriter sw)        {            int sum = map.Count();            int goodCount = map.Count(UnitState.Good);            int pickedCount = map.CountPicked();            sw.WriteLine("ROUTST 0");            sw.WriteLine("VERSID 3.2");            sw.WriteLine("TIMEST 20210802151052");            sw.WriteLine("MAPTYP e");            sw.WriteLine("DESIGN L4146Y");            sw.WriteLine("LOTMEA 1E130028");            sw.WriteLine("REFCNT 3");            sw.WriteLine("REFBIN XX");            sw.WriteLine("REFTP1 m");            sw.WriteLine("REFPX1 7");            sw.WriteLine("REFPY1 2");            sw.WriteLine("REFTP2 m");            sw.WriteLine("REFPX2 11");            sw.WriteLine("REFPY2 18");            sw.WriteLine("REFTP3 t");            sw.WriteLine("REFPX3 23");            sw.WriteLine("REFPY3 18");            sw.WriteLine("FFROT1 0");            sw.WriteLine("FNLOC1 0");            sw.WriteLine("ORLOC1 3");            sw.WriteLine("ROWCNT " + map.Rows.ToString());            sw.WriteLine("COLCNT " + map.Columns.ToString());            sw.WriteLine("WAFDIA 200");            sw.WriteLine("XDIES1 5.580");            sw.WriteLine("YDIES1 10.070");            sw.WriteLine("PASBIN 01");            sw.WriteLine("SUMPAS 459");            sw.WriteLine("COMPRE 2");            sw.WriteLine("SKIPDI 00,XX");            sw.WriteLine("REMARK SPECIAL INKING");            sw.WriteLine($"MAPID1 " + map.SubstrateID);            for (int i = 0; i < map.Rows; i++)            {                StringBuilder builder = new StringBuilder();                builder.Append("MAP" + (i + 1).ToString("000") + " ");                for (int j = 0; j < map.Columns; j++)                {                    var unit = OriginalBinCodes[0, 0, i, j];                    builder.Append(unit.FormattedCode);                }                sw.WriteLine(builder.ToString());            }            sw.WriteLine("[WorkingMap]");            for (int i = 0; i < map.Rows; i++)            {                StringBuilder builder = new StringBuilder();                builder.Append("MAP" + (i + 1).ToString("000") + " ");                for (int j = 0; j < map.Columns; j++)                {                    string binCode = "FA";                    var unit = map[i, j];                    if (unit.State == UnitState.Picked || unit.State == UnitState.Processed)                    {                        binCode = "FA";                    }                    else if (unit.State == UnitState.Reject)                    {                        binCode = "FB";                    }                    else                    {                        binCode = unit.Bin.FormattedCode;                    }                    builder.Append(binCode);                }                sw.WriteLine(builder.ToString());            }        }        private void SaveZW(Map map, StreamWriter sw)        {            int sum = map.Count();            int goodCount = map.Count(UnitState.Good);            int pickedCount = map.CountPicked();            sw.WriteLine("VERSID 3.4");            sw.WriteLine("WAFDIA 300");            sw.WriteLine("COLCNT " + map.Columns.ToString("000"));            sw.WriteLine("ROWCNT " + map.Rows.ToString("000"));            sw.WriteLine("COMPRE 2");            sw.WriteLine("DESIGN P7306R91011");            sw.WriteLine("FNLOC1 0");            sw.WriteLine("LOTMEA ZF242258");            sw.WriteLine("MAPTYP e");            sw.WriteLine("ORLOC1 3");            sw.WriteLine("PPFLAG 1");            sw.WriteLine("REFBIN XX");            sw.WriteLine("REFCNT 4");            sw.WriteLine("REFPX1 24");            sw.WriteLine("REFPY1 24");            sw.WriteLine("REFTP1 p");            sw.WriteLine("REFPX2 27");            sw.WriteLine("REFPY2 12");            sw.WriteLine("REFTP2 p");            sw.WriteLine("REFPX3 3");            sw.WriteLine("REFPY3 6");            sw.WriteLine("REFTP3 p");            sw.WriteLine("REFPX4 6");            sw.WriteLine("REFPY4 26");            sw.WriteLine("REFTP4 p");            sw.WriteLine("SKIPDI 00,XX");            sw.WriteLine("SUMPAS 000579");            sw.WriteLine("PICKCT 1");            sw.WriteLine("PASB01 01,02,03,04");            sw.WriteLine("PASBIN 01,02,03,04");            sw.WriteLine("PICK01 AG");            sw.WriteLine("SUMP01 000579");            sw.WriteLine("TIMEST 20221130054227");            sw.WriteLine($"MAPID1 " + map.SubstrateID);            for (int i = 0; i < map.Rows; i++)            {                StringBuilder builder = new StringBuilder();                builder.Append("MAP" + (i + 1).ToString("000") + " ");                for (int j = 0; j < map.Columns; j++)                {                    var unit = OriginalBinCodes[0, 0, i, j];                    builder.Append(unit.FormattedCode);                }                sw.WriteLine(builder.ToString());            }            sw.WriteLine("[WorkingMap]");            for (int i = 0; i < map.Rows; i++)            {                StringBuilder builder = new StringBuilder();                builder.Append("MAP" + (i + 1).ToString("000") + " ");                for (int j = 0; j < map.Columns; j++)                {                    string binCode = "FA";                    var unit = map[i, j];                    if (unit.State == UnitState.Picked || unit.State == UnitState.Processed)                    {                        binCode = "FA";                    }                    else if (unit.State == UnitState.Reject)                    {                        binCode = "FB";                    }                    else                    {                        binCode = unit.Bin.FormattedCode;                    }                    builder.Append(binCode);                }                sw.WriteLine(builder.ToString());            }        }    }}